CREATE TABLE categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), parent_id uuid REFERENCES categories(id), stable_key varchar(120) NOT NULL UNIQUE, external_reference varchar(100), level smallint NOT NULL DEFAULT 1 CHECK(level BETWEEN 1 AND 8), sort_order integer NOT NULL DEFAULT 0, is_active boolean NOT NULL DEFAULT true, allows_listings boolean NOT NULL DEFAULT true, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE category_translations(category_id uuid NOT NULL REFERENCES categories(id) ON DELETE CASCADE, language_code varchar(10) NOT NULL REFERENCES languages(code), name varchar(150) NOT NULL, slug varchar(180) NOT NULL, description text, seo_title varchar(200), seo_description varchar(320), PRIMARY KEY(category_id,language_code), UNIQUE(language_code,slug));
CREATE TABLE attributes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), stable_key varchar(120) NOT NULL UNIQUE, data_type varchar(30) NOT NULL CHECK(data_type IN ('text','long_text','integer','decimal','boolean','date','datetime','single_select','multi_select','color','measurement','location')), unit_code varchar(30), is_searchable boolean NOT NULL DEFAULT true, is_filterable boolean NOT NULL DEFAULT true, is_active boolean NOT NULL DEFAULT true);
CREATE TABLE attribute_translations(attribute_id uuid NOT NULL REFERENCES attributes(id) ON DELETE CASCADE, language_code varchar(10) NOT NULL REFERENCES languages(code), name varchar(150) NOT NULL, help_text text, placeholder varchar(200), PRIMARY KEY(attribute_id,language_code));
CREATE TABLE attribute_options(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), attribute_id uuid NOT NULL REFERENCES attributes(id) ON DELETE CASCADE, stable_key varchar(120) NOT NULL, sort_order integer NOT NULL DEFAULT 0, is_active boolean NOT NULL DEFAULT true, UNIQUE(attribute_id,stable_key));
CREATE TABLE attribute_option_translations(option_id uuid NOT NULL REFERENCES attribute_options(id) ON DELETE CASCADE, language_code varchar(10) NOT NULL REFERENCES languages(code), label varchar(150) NOT NULL, PRIMARY KEY(option_id,language_code));
CREATE TABLE category_attributes(category_id uuid NOT NULL REFERENCES categories(id) ON DELETE CASCADE, attribute_id uuid NOT NULL REFERENCES attributes(id) ON DELETE CASCADE, is_required boolean NOT NULL DEFAULT false, is_search_filter boolean NOT NULL DEFAULT true, sort_order integer NOT NULL DEFAULT 0, validation_rules jsonb NOT NULL DEFAULT '{}', PRIMARY KEY(category_id,attribute_id));
